def finish_order(work, slice):
    left = dict(work)
    finished = []
    while left:
        for name in list(left):
            left[name] -= min(slice, left[name])
            if left[name] == 0:
                finished.append(name)
                del left[name]
    return finished

def resolve(path):
    parts = []
    for p in path.split("/"):
        if p == "..":
            if parts:
                parts.pop()
        elif p and p != ".":
            parts.append(p)
    return "/" + "/".join(parts)
